import * as React from "react";

export type CrossCircleIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function CrossCircleIcon({ size = 20, ...props }: CrossCircleIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <circle cx="12" cy="12" r="8.5"/><path d="M9.5 9.5l5 5M14.5 9.5l-5 5"/>
    </svg>
  );
}
